// Original bilingual lessons. CEFR placements are curriculum guidance, not a certification.
// Each row: titles, explanations, structure, worked example + translation,
// a separate gap-fill with three options, and an incorrect contrast sentence.
const curriculum = {
  A1: [
    ['Be: am, is, are','Be үйл үг: am, is, are','Use be for identity, feelings and location. Match the form to the subject. Put not after be; move be before the subject in questions.','Хэн болох, мэдрэмж, байршлыг be үйл үгээр илэрхийлнэ. I-тэй am, he/she/it-тэй is, you/we/they-тэй are хэрэглэнэ. Үгүйсгэхэд not нэмнэ; асуухад be-г урд нь гаргана.','I am · he/she/it is · you/we/they are','My sister is a teacher.','Миний эгч багш.','They ___ at home.','are','is','am','My sister are a teacher.'],
    ['Subject and object pronouns','Биеийн төлөөний үг','Use subject pronouns before verbs and object pronouns after verbs or prepositions. I/me, he/him, she/her, we/us and they/them have different jobs.','Үйлдэл хийж буй хүнийг I/he/she/we/they, үйлдэлд өртөж буй хүнийг me/him/her/us/them гэж илэрхийлнэ. Объектын хэлбэр нь үйл үг эсвэл угтвар үгийн дараа орно.','She knows me. · I work with them.','He helps us every week.','Тэр бидэнд долоо хоног бүр тусалдаг.','Please call ___. (I)','me','I','my','Him helps we every week.'],
    ['Possessive adjectives and ’s','Хамаатуулах үг ба ’s','My, your, his, her, its, our and their come before nouns. Add ’s to a singular owner and an apostrophe after a regular plural ending in s.','My, your, his, her, its, our, their нь нэр үгийн өмнө орно. Ганц тооны эзэнд ’s, s-ээр төгссөн олон тооны эзэнд зөвхөн хасах тэмдэг нэмнэ.','my book · Anna’s book · the students’ books','This is our teacher’s desk.','Энэ манай багшийн ширээ.','She has a dog. ___ dog is small.','Her','She','Hers','This is we teacher’s desk.'],
    ['Articles: a, an, the','Ялгац гишүүн: a, an, the','Use a/an for one nonspecific countable thing, and the for an identifiable thing. Choose a or an by the next sound, not simply the spelling.','Тодорхой бус ганц тооны тоологдох нэрийн өмнө a/an, аль хэдийн тодорхой зүйлд the хэрэглэнэ. Эгшиг авианы өмнө an хэрэглэдэг тул an hour, a university гэж бичнэ.','a book · an apple · the book we discussed','I saw a cat. The cat was black.','Би муур харсан. Тэр муур хар байсан.','She is ___ engineer.','an','a','—','I saw an cat.'],
    ['Singular and plural nouns','Нэр үгийн ганц ба олон тоо','Most plural nouns take -s; some take -es or change -y to -ies. Learn irregular forms separately. Do not add -s to uncountable nouns such as information.','Олон тоонд ихэвчлэн -s, заримд нь -es нэмнэ; гийгүүлэгчийн дараах y нь -ies болно. Child → children зэрэг дүрмийн бус хэлбэрийг тусад нь сурна. Information гэх мэт тоологдохгүй нэрд -s нэмэхгүй.','book → books · city → cities · child → children','The children have two boxes.','Хүүхдүүдэд хоёр хайрцаг байна.','There are three ___ outside. (child)','children','childs','child','The childs have two box.'],
    ['This, that, these, those','Заах төлөөний үг','Use this/these for things near you and that/those for things farther away. This and that are singular; these and those are plural.','Ойр байгаа зүйлийг this/these, хол байгаа зүйлийг that/those гэж заана. This, that нь ганц тоо; these, those нь олон тоо.','this book · these books · that chair · those chairs','These shoes are new.','Эдгээр гутал шинэ.','___ is my bag here.','This','These','Those','This shoes are new.'],
    ['There is and there are','There is / there are','Use there is to introduce one thing or an uncountable noun; use there are for plural things. Use is there/are there in questions.','Нэг зүйл эсвэл тоологдохгүй зүйл байгааг there is, олон зүйл байгааг there are гэж хэлнэ. Асуухдаа is there / are there гэж байрлалыг солино.','There is + singular · There are + plural','There are two windows in this room.','Энэ өрөөнд хоёр цонх байна.','There ___ a park near my house.','is','are','be','There is two windows in this room.'],
    ['Present simple: statements','Энгийн одоо цаг','Use the present simple for routines and general facts. Add -s or -es with he/she/it; verbs after I/you/we/they use the base form.','Дадал, тогтмол үйлдэл, ерөнхий үнэнд энгийн одоо цаг хэрэглэнэ. He/she/it-ийн дараа үйл үгэнд -s/-es нэмнэ; бусад эзний дараа үндсэн хэлбэр хэрэглэнэ.','I work · she works · he watches','My father cooks every Sunday.','Аав маань ням гараг бүр хоол хийдэг.','She ___ English every day.','studies','study','studying','My father cook every Sunday.'],
    ['Do and does: questions and negatives','Do / does: асуулт ба үгүйсгэл','Use do/does for present simple questions and do not/does not for negatives. After does, the main verb returns to its base form. Be does not use do.','Энгийн одоо цагийн асуултад do/does, үгүйсгэлд do not/does not хэрэглэнэ. Does-ийн дараа үндсэн үйл үгэнд -s нэмэхгүй. Be үйл үгтэй асуултад do хэрэглэхгүй.','Does she work? · She doesn’t work.','Does your brother play tennis?','Ах чинь теннис тоглодог уу?','He doesn’t ___ coffee.','drink','drinks','drinking','Does your brother plays tennis?'],
    ['Question words','Асуух үгс','Who asks about people, where about places, when about time, why about reasons and how about manner. Use a question word before the auxiliary.','Who нь хүн, where нь газар, when нь цаг, why нь шалтгаан, how нь арга байдлыг асууна. Асуух үг туслах үйл үгийн өмнө байрлана.','Where do you live? · Why is she late?','When does the train leave?','Галт тэрэг хэзээ хөдлөх вэ?','___ do you live? — In Ulaanbaatar.','Where','When','Who','When the train does leave?'],
    ['Adverbs of frequency','Давтамжийн дайвар үг','Always, usually, often, sometimes and never describe frequency. They normally go before a main verb but after be. Never already has negative meaning.','Always, usually, often, sometimes, never нь давтамж илэрхийлнэ. Гол үйл үгийн өмнө, харин be-ийн дараа ихэвчлэн орно. Never өөрөө үгүйсгэсэн утгатай.','She often reads. · She is often busy.','I usually walk to school.','Би сургууль руу ихэвчлэн алхдаг.','He ___ late. (never)','is never','never is being','does never is','I am usually walk to school.'],
    ['Present continuous','Үргэлжилж буй одоо цаг','Use am/is/are + -ing for an activity happening now or a temporary situation. Keep be in both statements and questions.','Яг одоо болж буй эсвэл түр зуурын үйлдлийг am/is/are + -ing хэлбэрээр илэрхийлнэ. Батлах болон асуух өгүүлбэрт be-г орхиж болохгүй.','subject + am/is/are + verb-ing','She is reading a book now.','Тэр одоо ном уншиж байна.','Look! The baby ___.','is sleeping','sleeps every day','sleep','She reading a book now.'],
    ['Present simple or continuous?','Энгийн ба үргэлжилж буй одоо цаг','Use the simple for a routine and the continuous for an action in progress. State verbs such as know and want normally use simple forms.','Дадалд энгийн, тухайн мөчид болж буй үйлдэлд үргэлжилж буй цаг хэрэглэнэ. Know, want зэрэг төлөв заасан үйл үг ихэвчлэн энгийн хэлбэртэй.','every day → simple · right now → continuous','I work at a bank, but today I am working from home.','Би банкинд ажилладаг ч өнөөдөр гэрээс ажиллаж байна.','Listen! Someone ___ at the door.','is knocking','knock','knocks every day','I am knowing the answer.'],
    ['Can and can’t','Чадвар илэрхийлэх can / can’t','Use can for ability and permission, and can’t for inability or prohibition. The next verb is a base form without to. Can has no third-person -s.','Чадвар, зөвшөөрөлд can, чадахгүй эсвэл хориотойг хэлэхэд can’t хэрэглэнэ. Дараах үйл үг to-гүй үндсэн хэлбэртэй; can-д -s нэмэхгүй.','can/can’t + base verb','She can swim very well.','Тэр маш сайн сэлж чадна.','Can you ___ me?','help','to help','helps','She can swims very well.'],
    ['Imperatives and let’s','Захирах ба хамт хийх санал','Use the base verb for instructions and don’t + base verb for negative instructions. Use let’s + base verb to suggest doing something together.','Заавар өгөхөд үйл үгийн үндсэн хэлбэр, хориглоход don’t + үндсэн хэлбэр хэрэглэнэ. Let’s + үйл үг нь хамт хийх санал юм.','Open the door. · Don’t run. · Let’s go.','Please turn off your phone.','Утсаа унтраана уу.','___ touch that hot pan.','Don’t','Doesn’t','Not to','Please turns off your phone.'],
    ['Prepositions of place','Байрлалын угтвар үг','Use in for an enclosed space, on for a surface and at for a point or activity location. Under, behind, between and next to give more precise positions.','Битүү орон зайд in, гадаргуу дээр on, цэг эсвэл үйл ажиллагааны газарт at хэрэглэнэ. Under, behind, between, next to нь байрлалыг нарийвчилна.','in a box · on a table · at the station','The keys are on the table.','Түлхүүрүүд ширээн дээр байна.','The picture hangs ___ the wall.','on','in','under','The keys are on at the table.'],
    ['Prepositions of time','Цагийн угтвар үг','Use at with clock times, on with days and dates, and in with months, years and parts of the day. Common exceptions include at night and at the weekend in British English.','Тодорхой цагтай at, өдөр ба огноотой on, сар/жил/өдрийн хэсэгтэй in хэрэглэнэ. At night нь түгээмэл онцгой хэлбэр.','at 9:00 · on Monday · in June','Our class starts at nine on Monday.','Манай хичээл даваа гарагт есөн цагт эхэлдэг.','My birthday is ___ July.','in','on','at','Our class starts in nine on Monday.'],
    ['Past simple of be','Be үйл үгийн өнгөрсөн цаг','Use was with I/he/she/it and were with you/we/they for past states. Put not after was/were; invert them for questions.','Өнгөрсөн үеийн төлөвт I/he/she/it-тэй was, you/we/they-тэй were хэрэглэнэ. Үгүйсгэлд not нэмнэ; асуултад was/were-г урд нь гаргана.','I was · they were · Was she …?','We were tired yesterday.','Бид өчигдөр ядарсан байсан.','She ___ at school yesterday.','was','were','is being','We was tired yesterday.'],
    ['Past simple: actions','Энгийн өнгөрсөн цаг','Use past simple for completed past actions. Regular verbs take -ed; irregular verbs have special forms. Questions and negatives use did + base verb.','Дууссан өнгөрсөн үйлдэлд past simple хэрэглэнэ. Зөв үйл үгэнд -ed нэмдэг; дүрмийн бус хэлбэрийг сурна. Асуулт, үгүйсгэлд did + үндсэн үйл үг хэрэглэнэ.','worked · went · Did she go? · didn’t go','They visited their grandparents last week.','Тэд өнгөрсөн долоо хоногт өвөө, эмээдээ зочилсон.','Did you ___ the film?','see','saw','seen','Did they visited their grandparents?'],
    ['Countable nouns and some/any','Тоологдох нэр ба some / any','Countable nouns can be singular or plural; uncountable nouns normally cannot take a/an. Use some in ordinary affirmative statements and any in ordinary negatives and questions.','Тоологдох нэр ганц/олон тоотой; тоологдохгүй нэрийн өмнө ихэвчлэн a/an тавихгүй. Энгийн батлахад some, үгүйсгэл ба асуултад any хэрэглэнэ. Санал, хүсэлтэд some хэрэглэж болно.','some water · any apples · a piece of advice','There is some milk in the fridge.','Хөргөгчинд сүү байна.','We haven’t got ___ bread.','any','a','many','There is a milk in the fridge.'],
  ],
  A2: [
    ['Comparatives','Харьцуулсан зэрэг','Use -er for many short adjectives and more for most longer adjectives. Use than for the second item. Good becomes better and bad becomes worse.','Богино тэмдэг нэрд ихэвчлэн -er, урт тэмдэг нэрийн өмнө more хэрэглэнэ. Харьцуулж буй хоёр дахь зүйлээс өмнө than орно. Good → better, bad → worse.','smaller than · more useful than','This exercise is easier than the last one.','Энэ дасгал өмнөхөөсөө амархан.','My bag is ___ than yours.','heavier','more heavyer','heaviest','This exercise is more easier than the last one.'],
    ['Superlatives','Давуу зэрэг','Use the + -est or the most to compare one item with an entire group. Good becomes the best. Use in with a place or group and of with a set of items.','Нэг зүйлийг бүх бүлэгтэй харьцуулахад the + -est эсвэл the most хэрэглэнэ. Good → the best. Газартай in, зүйлсийн багцтай of хэрэглэж болно.','the tallest in the class · the most interesting','She is the youngest person in our team.','Тэр манай багийн хамгийн залуу хүн.','This is ___ book I have read.','the most interesting','most interesting than','the more interesting','She is youngest person in our team.'],
    ['Much, many, a few, a little','Тоо хэмжээ заах үгс','Use many and a few with plural countable nouns; use much and a little with uncountable nouns. A lot of works with both. Few/little without a emphasise scarcity.','Олон тооны тоологдох нэртэй many, a few; тоологдохгүй нэртэй much, a little хэрэглэнэ. A lot of нь хоёулантай хэрэглэгдэнэ. A-гүй few/little нь бараг үгүй гэсэн санаа өгнө.','many books · much time · a little water','We have a little time before the train.','Галт тэрэг хөдлөхөөс өмнө бидэнд бага зэрэг хугацаа байна.','How ___ students are in your class?','many','much','a little','We have a few time before the train.'],
    ['Too and enough','Too ба enough','Too means more than needed; enough means sufficient. Put enough after adjectives but before nouns. Too much/many modifies quantities.','Too нь хэрэгцээнээс хэтэрсэн, enough нь хангалттай гэсэн утгатай. Enough нь тэмдэг нэрийн дараа, нэр үгийн өмнө орно. Хэмжээнд too much/many хэрэглэнэ.','too hot · warm enough · enough money','The water is warm enough to swim in.','Ус сэлэхэд хангалттай бүлээн байна.','This bag is ___ heavy to carry.','too','enough','many','The water is enough warm to swim in.'],
    ['Will and going to','Will ба going to ирээдүй цаг','Use will for a decision made now, offers and predictions. Use going to for an existing intention or a prediction based on present evidence. Both take a base verb.','Яг одоо гаргасан шийдвэр, санал, таамагт will хэрэглэнэ. Өмнө төлөвлөсөн санаа эсвэл одоогийн нотолгоотой таамагт going to хэрэглэнэ. Дараа нь үндсэн үйл үг орно.','will + verb · am/is/are going to + verb','Look at those clouds! It is going to rain.','Тэр үүлсийг хар! Бороо орох нь.','The phone is ringing. I ___ answer it.','will','am going','will to','It is going rain.'],
    ['Present continuous for arrangements','Тохирсон ирээдүйд present continuous','Use present continuous for a future arrangement, usually with another person and a time expression. Use present simple for timetables.','Бусадтай тохирсон ирээдүйн үйл явдалд үргэлжилж буй одоо цагийг цагийн заалттай хэрэглэнэ. Харин албан цагийн хуваарьт энгийн одоо цаг хэрэглэнэ.','I’m meeting … tomorrow · The train leaves at …','I am meeting Sara at six tomorrow.','Би маргааш зургаад Саратай уулзахаар тохирсон.','The train ___ at 8:15 tomorrow.','leaves','leave','is leave','I meeting Sara at six tomorrow.'],
    ['Past continuous','Үргэлжилж байсан өнгөрсөн цаг','Use was/were + -ing for an activity in progress at a past time. A past simple event can interrupt it. While often introduces the longer activity.','Өнгөрсөн тодорхой мөчид үргэлжилж байсан үйлдлийг was/were + -ing хэлбэрээр илэрхийлнэ. Богино үйлдэл түүнийг тасалбал past simple хэрэглэнэ.','was/were + verb-ing · when + past simple','I was cooking when the phone rang.','Утас дуугарахад би хоол хийж байсан.','They ___ TV at nine last night.','were watching','was watching','watch','I were cooking when the phone rang.'],
    ['Present perfect: experience','Төгс одоо цаг: туршлага','Use have/has + past participle for an experience at an unspecified time before now. Use ever in questions and never for no experience. Do not combine it with a finished past time such as yesterday.','Одоогоос өмнөх тодорхойгүй үеийн туршлагыг have/has + past participle хэлбэрээр илэрхийлнэ. Асуултад ever, огт хийж байгаагүйд never хэрэглэнэ. Yesterday зэрэг дууссан цагтай past simple хэрэглэнэ.','have/has + past participle','She has visited Japan twice.','Тэр Японд хоёр удаа очиж байсан.','Have you ever ___ sushi?','eaten','ate','eat','She has visited Japan yesterday.'],
    ['Just, already and yet','Just, already, yet','Use just for a very recent action, already for something earlier than expected, and yet for something expected but unfinished or in questions. Yet normally goes at the end.','Дөнгөж хийснийг just, аль хэдийн болсныг already, хүлээгдэж буйг yet гэж хэлнэ. Yet нь ихэвчлэн асуулт, үгүйсгэл өгүүлбэрийн төгсгөлд орно.','has just finished · has already left · hasn’t arrived yet','I have already done my homework.','Би гэрийн даалгавраа аль хэдийн хийсэн.','She hasn’t called ___.','yet','already has','just has','I have already did my homework.'],
    ['For and since','For ба since','Use for with a duration and since with a starting point. Present perfect connects a past beginning to the present when the situation continues.','Үргэлжилсэн хугацаанд for, эхэлсэн цэгт since хэрэглэнэ. Өнгөрсөнд эхлээд одоо ч үргэлжилж буй төлөвийг present perfect-оор илэрхийлнэ.','for three years · since 2020','We have lived here for five years.','Бид энд таван жил амьдарч байна.','I have known her ___ 2019.','since','for','during','We have lived here since five years.'],
    ['Should and shouldn’t','Зөвлөгөө өгөх should','Use should/shouldn’t + base verb for advice and what is sensible. It is usually weaker than must, which expresses strong obligation.','Зөвлөгөө, зохистой үйлдэлд should/shouldn’t + үндсэн үйл үг хэрэглэнэ. Энэ нь хүчтэй шаардлага илэрхийлэх must-аас зөөлөн.','should + base verb · shouldn’t + base verb','You should drink more water.','Чи илүү их ус уух хэрэгтэй.','You look tired. You ___ rest.','should','should to','shoulds','You should to drink more water.'],
    ['Must, have to and don’t have to','Үүрэг ба шаардлага','Must and have to express obligation. Mustn’t means prohibited; don’t have to means not necessary. Use had to for a past obligation.','Must, have to нь үүрэг шаардлага илэрхийлнэ. Mustn’t нь хориотой, don’t have to нь заавал шаардлагагүй гэсэн ялгаатай утгатай. Өнгөрсөн үүрэгт had to хэрэглэнэ.','mustn’t = prohibited · don’t have to = optional','You must not park here.','Та энд машинаа тавьж болохгүй.','It is optional. You ___ come.','don’t have to','mustn’t','have not','You don’t have to park here because it is forbidden.'],
    ['Could and polite requests','Could ба эелдэг хүсэлт','Use could for general past ability and for polite requests now. Could you + base verb asks someone to act; could I asks permission.','Өнгөрсөн үеийн ерөнхий чадвар болон одоогийн эелдэг хүсэлтэд could хэрэглэнэ. Could you + үндсэн үйл үг нь бусдаас хийхийг, could I нь зөвшөөрөл хүснэ.','Could you help? · Could I leave?','Could you open the window, please?','Цонх нээж өгч болох уу?','When I was six, I ___ read.','could','can to','could to','Could you to open the window?'],
    ['Gerunds after like and enjoy','Үйл үгийн -ing нэршил','Use -ing after enjoy, avoid and finish. Like and love can take -ing or to-infinitive with small differences in meaning. A gerund can also be the subject.','Enjoy, avoid, finish-ийн дараа үйл үгийг -ing хэлбэрээр хэрэглэнэ. Like/love-ийн дараа -ing болон to-infinitive аль аль нь байж болно. -Ing хэлбэр өгүүлбэрийн эзэн ч болж болно.','enjoy doing · avoid doing · Swimming is fun.','She enjoys reading in the evening.','Тэр орой ном унших дуртай.','We finished ___ the room.','cleaning','to cleaning','clean','She enjoys to read in the evening.'],
    ['Infinitives and purpose','To-infinitive ба зорилго','Use to + base verb after want, decide and hope, and to explain purpose. Do not use for + base verb to express a person’s purpose.','Want, decide, hope-ийн дараа to + үндсэн үйл үг хэрэглэнэ. Мөн юунд зориулж хийснийг ингэж илэрхийлнэ. Хүний зорилгыг for + үндсэн үйл үгээр илэрхийлэхгүй.','want to learn · went there to study','I went to the shop to buy bread.','Би талх авахын тулд дэлгүүр явсан.','She decided ___ early.','to leave','leaving to','leave','I went to the shop for buy bread.'],
    ['Zero and first conditionals','Тэг ба нэгдүгээр нөхцөл','Use if + present, present for general results. Use if + present, will + verb for a real future possibility. Do not normally put will in the if-clause.','Ерөнхий үр дүнд if + present, present; бодит ирээдүйн боломжид if + present, will + үйл үг хэрэглэнэ. Нөхцөл заасан if хэсэгт ихэвчлэн will тавихгүй.','If water freezes, it expands. · If it rains, I’ll stay.','If you study, you will improve.','Чи хичээллэвэл сайжирна.','If it ___ tomorrow, we will stay home.','rains','will rain','rained','If you will study, you will improve.'],
    ['Adjectives and adverbs','Тэмдэг нэр ба дайвар үг','Adjectives describe nouns; adverbs describe actions. Many adverbs end in -ly, but good becomes well. Hard and fast can be both adjectives and adverbs.','Тэмдэг нэр нь нэрийг, дайвар үг нь үйлдлийг тодорхойлно. Олон дайвар үг -ly төгсгөлтэй ч good → well болно. Hard, fast нь хоёр үүрэгтэй байж болно.','a careful driver · drives carefully','She speaks English well.','Тэр англиар сайн ярьдаг.','He drives very ___. (careful)','carefully','careful','carefuler','She speaks English good.'],
    ['Possessive pronouns and reflexives','Хамаатуулах төлөөний ба өөрийгөө заах үг','Mine, yours and theirs replace possessive adjective + noun. Use myself/yourself/herself when subject and object refer to the same person.','Mine, yours, theirs нь хамаатуулах үг + нэрийн оронд орно. Эзэн болон объект нь нэг хүн бол myself/yourself/herself зэрэг өөрийгөө заах үг хэрэглэнэ.','my book → mine · She taught herself.','This bag is mine. I bought it myself.','Энэ цүнх минийх. Би өөрөө авсан.','He cut ___ while cooking.','himself','hisself','he','This bag is my.'],
    ['Linking ideas: and, but, because, so','Санаа холбох үгс','And adds an idea, but contrasts, because introduces a reason and so introduces a result. In standard written English, avoid because and so together for the same relationship.','And нь нэмэх, but нь эсрэгцүүлэх, because нь шалтгаан, so нь үр дүнг илэрхийлнэ. Нэг шалтгаан-үр дүнг because ба so хоёроор зэрэг холбохгүй.','I stayed because it rained. · It rained, so I stayed.','I was hungry, so I made lunch.','Би өлссөн тул өдрийн хоол хийсэн.','I stayed inside ___ it was cold.','because','so that because','because of it','Because I was hungry, so I made lunch.'],
    ['Movement and common phrasal verbs','Хөдөлгөөн ба нийлмэл үйл үг','To marks a destination, into entry, out of exit and across movement from one side to another. Learn common verb-particle units such as get up and turn on as meanings together.','To нь очих чиглэл, into нь дотогш, out of нь гадагш, across нь хөндлөн хөдөлгөөн заана. Get up, turn on зэрэг үйл үг + хэсгийг нэг утгаар сурна.','go to · walk into · get up · turn on','She walked into the room and turned on the light.','Тэр өрөөнд орж гэрлээ асаасан.','Please turn ___ the light; it is dark.','on','up to','into','She walked to into the room.'],
  ],
  B1: [
    ['Present perfect or past simple?','Present perfect ба past simple','Use past simple with a finished past time. Use present perfect when the time is unfinished or the result matters now. Been describes a completed visit; gone usually means the person is still away.','Дууссан тодорхой цагтай past simple, одоотой холбоотой үр дүн эсвэл дуусаагүй хугацаанд present perfect хэрэглэнэ. Been нь очоод ирсэн, gone нь яваад одоо эзгүй гэсэн санаатай.','yesterday → past simple · so far → present perfect','I lost my keys yesterday, but I have found them now.','Би өчигдөр түлхүүрээ гээсэн ч одоо олсон.','She ___ three emails so far today.','has written','wrote yesterday','has wrote','I have lost my keys yesterday.'],
    ['Present perfect continuous','Төгс үргэлжилсэн одоо цаг','Use have/has been + -ing for an activity continuing from the past or recent activity with visible results. The simple perfect often emphasises completion or quantity; continuous emphasises duration.','Өнгөрсөнд эхлээд үргэлжилж буй эсвэл саяхны үр дүн нь харагдах үйлдэлд have/has been + -ing хэрэглэнэ. Энгийн төгс цаг нь дуусалт, тоо хэмжээг; үргэлжилсэн нь хугацааг онцолдог.','have/has been + verb-ing','She has been studying for two hours.','Тэр хоёр цагийн турш хичээллэж байна.','We ___ for the bus since eight.','have been waiting','are waiting since','have waiting','She has studying for two hours.'],
    ['Past perfect','Өнгөрсөн төгс цаг','Use had + past participle for an event before another past reference point. It makes the order clear when you look back from a past story. Do not use it for every past action.','Өнгөрсөн өөр нэг үйл явдлаас өмнө дууссан үйлдэлд had + past participle хэрэглэнэ. Өнгөрсөн түүхээс түүнээс өмнөх үе рүү эргэж буйг тодруулна. Бүх өнгөрсөн үйлдэлд хэрэглэхгүй.','had + past participle · before a past event','When I arrived, the film had started.','Намайг ирэхэд кино эхэлчихсэн байсан.','She couldn’t enter because she ___ her key.','had forgotten','has forget','forgets','When I arrived, the film has started.'],
    ['Narrative tenses','Өнгөрсөн түүх өгүүлэх цагууд','Use past simple for main events, past continuous for background and past perfect for earlier events. Choose the tense by the time relationship, not by the order of clauses alone.','Түүхийн гол үйл явдалд past simple, арын нөхцөлд past continuous, түүнээс өмнөх үйлдэлд past perfect хэрэглэнэ. Цагийг өгүүлбэрийн байрлалаар бус үйл явдлын холбоогоор сонгоно.','background: was doing · earlier: had done · event: did','It was raining when I realised I had left my coat at home.','Гадуур хувцсаа гэртээ мартсанаа ойлгоход бороо орж байсан.','I ___ when someone knocked on the door.','was sleeping','had sleep','sleep now','It was rain when I realised my mistake.'],
    ['Used to and be used to','Used to ба be used to','Used to + base verb describes a past habit or state that no longer holds. Be used to + noun/-ing means be accustomed; get used to describes the process of adapting.','Used to + үндсэн үйл үг нь одоо байхгүй өнгөрсөн дадал, төлөв. Be used to + нэр/-ing нь дассан, get used to нь дасаж буйг илэрхийлнэ.','used to live · am used to living','I used to live alone, but now I share a flat.','Би өмнө ганцаараа амьдардаг байсан ч одоо байр хуваан амьдардаг.','She is used to ___ early.','getting up','get up','got up','I am used to live alone.'],
    ['Future continuous','Үргэлжлэх ирээдүй цаг','Use will be + -ing for an activity in progress at a future time. It can also politely ask about someone’s expected plans.','Ирээдүйн тодорхой мөчид үргэлжилж байх үйлдлийг will be + -ing хэлбэрээр илэрхийлнэ. Мөн хүний төлөвлөгөөг зөөлөн асуухад хэрэглэж болно.','will be + verb-ing','At ten tomorrow, I will be flying to Seoul.','Маргааш аравт би Сөүл рүү нисэж байх болно.','This time next week, we ___ on the beach.','will be relaxing','will relaxing','will be relax','At ten tomorrow, I will flying to Seoul.'],
    ['Second conditional','Хоёрдугаар нөхцөл','Use if + past simple, would + base verb for an unreal or unlikely present/future situation. Were is common for all persons in formal hypothetical clauses: if I were you.','Одоо эсвэл ирээдүйн бодит бус, магадлал багатай нөхцөлийг if + past simple, would + үндсэн үйл үгээр илэрхийлнэ. Албан хэлэнд if I were you гэж хэрэглэнэ.','If + past simple, would + verb','If I had more time, I would learn Italian.','Надад илүү цаг байсан бол итали хэл сурах байсан.','If she knew the answer, she ___ us.','would tell','will tells','would told','If I would have more time, I would learn Italian.'],
    ['Third conditional','Гуравдугаар нөхцөл','Use if + past perfect, would have + past participle for an imagined different past. It describes something that did not happen and its unreal result. Could/might have express ability or possibility.','Өнгөрсөнд болоогүй өөр нөхцөл, түүний төсөөлсөн үр дүнг if + past perfect, would have + past participle-ээр хэлнэ. Could/might have нь боломж, магадлалыг илэрхийлнэ.','If + had done, would have done','If I had left earlier, I would have caught the bus.','Эрт гарсан бол автобусандаа амжих байсан.','If she had studied, she ___ the exam.','would have passed','would pass yesterday','will have pass','If I had left earlier, I would caught the bus.'],
    ['Modals of deduction','Таамаглан дүгнэх модал үг','Use must for a strong positive deduction, can’t for a strong negative deduction and may/might/could for a possibility. Must here expresses a conclusion, not an obligation.','Баттай гэж дүгнэхэд must, боломжгүй гэж дүгнэхэд can’t, боломжтой гэж үзэхэд may/might/could хэрэглэнэ. Энд must нь үүрэг бус дүгнэлт юм.','must be · can’t be · might be','The lights are on. Someone must be at home.','Гэрэл асаалттай байна. Гэрт хүн байгаа нь гарцаагүй.','That ___ be Ali; he is abroad.','can’t','must to','can’t to','Someone must to be at home.'],
    ['Past modals: should have and might have','Өнгөрсөн үеийн модал хэлбэр','Use modal + have + past participle to look back. Should have expresses criticism or regret; might have suggests a possible past event. Must have is a strong past deduction.','Modal + have + past participle нь өнгөрсөнд хамаарна. Should have нь шүүмжлэл, харамсал; might have нь өнгөрсөн боломж; must have нь баттай дүгнэлт илэрхийлнэ.','should have done · might have done · must have done','You should have called before coming.','Чи ирэхээсээ өмнө утасдах хэрэгтэй байсан.','He may ___ the train.','have missed','has missed','have miss','You should have call before coming.'],
    ['The passive: present and past','Үйлдэгдэх хэв: одоо ба өнгөрсөн','Use be + past participle when the action or receiver matters more than the agent. Change be for tense. Add by + agent only when useful.','Үйлдэгчээс илүү үйлдэл эсвэл өртөж буй зүйл чухал бол be + past participle хэрэглэнэ. Be-г цагт тохируулна. Үйлдэгчийг хэрэгтэй үед by-гаар нэмнэ.','is made · was built · by the artist','The bridge was built in 1998.','Гүүрийг 1998 онд барьсан.','English ___ in many countries.','is spoken','speaks','is speak','The bridge was build in 1998.'],
    ['Reported statements','Дам ярианы батлах өгүүлбэр','After a past reporting verb, tenses often move back: am → was, have done → had done, will → would. Pronouns and time words change with context; universally true facts need not shift.','Өнгөрсөн хэлэх үйл үгийн дараа цаг ихэвчлэн нэг алхам ухарна: am → was, have done → had done, will → would. Төлөөний үг, цагийн заалт нөхцөлдөө тохирч өөрчлөгдөнө. Үргэлж үнэн баримтын цагийг заавал ухраахгүй.','She said (that) she was tired.','He said that he would call the next day.','Тэр маргааш нь утасдана гэж хэлсэн.','“I am busy,” she said. → She said she ___ busy.','was','is being yesterday','be','He said that he will called the next day.'],
    ['Reported questions and commands','Дам асуулт ба тушаал','Reported questions use statement order, without do/does/did. Use if/whether for yes/no questions. Report commands with tell/ask + object + (not) to-infinitive.','Дам асуултад батлах өгүүлбэрийн дараалал хэрэглэж, do/does/did-ийг хасна. Тийм/үгүй асуултад if/whether орно. Тушаалыг tell/ask + объект + (not) to-infinitive-ээр дамжуулна.','asked where I lived · told me to wait','She asked me where I lived.','Тэр намайг хаана амьдардгийг асуусан.','He told us ___ quiet.','to be','be','being to','She asked me where did I live.'],
    ['Defining relative clauses','Тодотгох хамаатуулах өгүүлбэр','Use who for people, which for things and that for either in defining clauses. These clauses identify the noun and do not take separating commas. An object relative pronoun can be omitted.','Хүнийг who, зүйлийг which, хоёуланг нь that-ээр тодотгож болно. Аль нэр болохыг ялгаж буй хэсгийг таслалаар салгахгүй. Объектын хамаатуулах үгийг орхиж болно.','the person who called · the book (that) I bought','The woman who lives next door is a doctor.','Хажууд амьдардаг эмэгтэй эмч.','This is the book ___ I told you about.','that','who','what','The woman which lives next door is a doctor.'],
    ['Question tags and short agreements','Асуултын сүүл ба санал нийлэх','A positive statement usually has a negative tag and vice versa. Match the auxiliary and subject. So + auxiliary + subject agrees with positives; neither does the same for negatives.','Батлах өгүүлбэрийн сүүлд ихэвчлэн үгүйсгэсэн, үгүйсгэлийн сүүлд баталсан tag орно. Туслах үйл үг, эзнийг тохируулна. Эерэг саналд so, сөрөгт neither + туслах үг + эзэн хэрэглэнэ.','She is here, isn’t she? · So do I. · Neither do I.','You have met him, haven’t you?','Чи түүнтэй уулзаж байсан, тийм үү?','She doesn’t drive, ___?','does she','doesn’t she','is she','You have met him, don’t you?'],
    ['Gerund or infinitive: changes of meaning','-Ing / to хэлбэрээс утга өөрчлөгдөх','Remember doing means recall a past action; remember to do means not forget a task. Stop doing ends an activity; stop to do pauses another activity for a purpose.','Remember doing нь хийснээ санах; remember to do нь хийхээ мартахгүй байх. Stop doing нь үйлдлээ зогсоох; stop to do нь өөр зүйлээ түр зогсоож уг үйлдлийг хийх гэсэн ялгаатай.','remember doing / to do · stop doing / to do','I stopped walking to answer the phone.','Би утсаа авахын тулд алхахаа түр зогсоосон.','Remember ___ the door before you leave.','to lock','locking yesterday','lock','I stopped to walking.'],
    ['Indirect questions','Шууд бус эелдэг асуулт','Use an introductory question such as Could you tell me … followed by statement word order. Do not invert the embedded subject and verb. Use if/whether for yes/no questions.','Could you tell me … гэх мэт эхлэлийн дараа батлах өгүүлбэрийн дарааллаар асууна. Доторх эзэн, үйл үгийг сольж болохгүй. Тийм/үгүй асуултад if/whether хэрэглэнэ.','Could you tell me where the bank is?','Do you know what time the shop closes?','Дэлгүүр хэдэн цагт хаадгийг мэдэх үү?','Could you tell me where ___?','the station is','is the station','does the station','Do you know what time does the shop close?'],
    ['Contrast, reason and result clauses','Эсрэгцэл, шалтгаан, үр дүн','Although/even though take a clause; despite/in spite of take a noun or -ing. Because takes a clause; because of takes a noun phrase. However links contrasting sentences.','Although/even though-ийн дараа өгүүлбэр, despite/in spite of-ийн дараа нэр эсвэл -ing орно. Because-ийн дараа өгүүлбэр, because of-ийн дараа нэрийн бүлэг орно. However нь эсрэг санаатай өгүүлбэрүүдийг холбоно.','although it rained · despite the rain','Although it was cold, we went for a walk.','Хүйтэн байсан ч бид салхинд гарсан.','We went out despite ___ tired.','being','we were','although','Despite it was cold, we went for a walk.'],
    ['Both, either, neither and each','Both / either / neither / each','Both refers to two together, either to one of two and neither to not one of two. Each/every + singular noun normally takes a singular verb. Use of before a pronoun or definite plural noun group.','Both нь хоёул, either нь хоёрын аль нэг, neither нь аль нь ч биш. Each/every + ганц тооны нэрийн дараа ганц тооны үйл үг хэрэглэнэ. Төлөөний үг, тодорхой бүлгийн өмнө of орно.','both of them · neither of the answers · each student is','Each student has a different book.','Сурагч бүр өөр номтой.','___ of the two keys works; both are broken.','Neither','Both','Every','Each student have a different book.'],
    ['Separable phrasal verbs','Салгаж хэрэглэдэг нийлмэл үйл үг','With separable phrasal verbs, a noun object can often go before or after the particle. A pronoun object must go between. Inseparable verbs such as look after keep the object after the preposition.','Салдаг нийлмэл үйл үгэнд нэр объектыг хэсгийн өмнө эсвэл дараа тавьж болно. Төлөөний объектыг дунд нь заавал тавина. Look after зэрэг салдаггүй хэлбэрт объект дараа нь орно.','turn the light off / turn off the light · turn it off','Please turn it off before you leave.','Гарахаасаа өмнө үүнийг унтраагаарай.','I found the word. I looked ___ in a dictionary.','it up','up it','up to it','Please turn off it before you leave.'],
  ],
  B2: [
    ['Past perfect continuous','Өнгөрсөн төгс үргэлжилсэн цаг','Use had been + -ing for an ongoing activity before a past point, often to explain a past result or emphasise duration. Avoid it with most state verbs.','Өнгөрсөн тодорхой мөчөөс өмнө үргэлжилж байсан үйлдэл, түүний үр дүн эсвэл хугацааг had been + -ing хэлбэрээр онцолно. Ихэнх төлөвийн үйл үгтэй хэрэглэхгүй.','had been + verb-ing','She was tired because she had been running.','Тэр гүйж байсан учраас ядарсан байлаа.','They ___ for an hour when help arrived.','had been waiting','have been waiting','had waiting','She had been run for an hour.'],
    ['Future perfect','Ирээдүйн төгс цаг','Use will have + past participle for something completed before a future point. By and by the time commonly mark the deadline. A time clause after by the time normally uses present simple.','Ирээдүйн тодорхой мөчөөс өмнө дууссан байх үйлдлийг will have + past participle-ээр илэрхийлнэ. By/by the time нь хугацааны зааг заана. By the time-ийн дараах ирээдүйд present simple хэрэглэнэ.','will have done + by a future time','By Friday, I will have finished the report.','Баасан гараг гэхэд би тайлангаа дуусгасан байна.','By next June, she ___ her course.','will have completed','will has completed','will have complete','By Friday, I will have finish the report.'],
    ['Future perfect continuous','Ирээдүйн төгс үргэлжилсэн цаг','Use will have been + -ing to measure the duration of an activity up to a future point. It focuses on how long, rather than how much is complete.','Ирээдүйн нэг мөч хүртэл хэдий хугацаанд үргэлжилсэн байхыг will have been + -ing хэлбэрээр илэрхийлнэ. Дууссан хэмжээнээс илүү хугацааг онцолно.','will have been + verb-ing + for','In May, I will have been working here for ten years.','Тавдугаар сард би энд арван жил ажилласан байх болно.','By noon, we ___ for four hours.','will have been driving','will have driving','will been driven','I will have been work here for ten years.'],
    ['Mixed conditionals','Холимог нөхцөл','Combine past and present time when cause and result are in different periods. A past unreal cause uses if + had done; a present unreal result uses would + base verb. The reverse combination is also possible.','Шалтгаан, үр дүн нь өөр цагт бол нөхцөлийн хэлбэрүүдийг хослуулна. Өнгөрсөн бодит бус шалтгаанд if + had done, одоогийн үр дүнд would + үндсэн үйл үг хэрэглэнэ. Эсрэг хослол ч боломжтой.','If I had studied medicine, I would be a doctor now.','If she had slept well, she would not be tired now.','Тэр сайн унтсан бол одоо ядрахгүй байх байсан.','If I had taken that job, I ___ in London now.','would live','would have lived now','will living','If she had slept well, she would not been tired now.'],
    ['Wish and if only','Wish / if only: хүсэл ба харамсал','Use wish/if only + past simple for an unreal present, past perfect for past regret and would for a desired change in behaviour or circumstances. Could expresses a wished-for ability.','Бодит бус одоогийн хүсэлд wish/if only + past simple, өнгөрсөн харамсалд past perfect, өөрчлөгдөхийг хүссэн үйлдэлд would хэрэглэнэ. Чадвар хүсэхэд could орно.','wish I knew · wish I had known · wish it would stop','I wish I had listened to your advice.','Чиний зөвлөгөөг сонссон ч болоосой.','I don’t know the answer. I wish I ___.','knew','know','had knew','I wish I have listened to your advice yesterday.'],
    ['Would for past habits','Өнгөрсөн дадалд would','Use would + base verb for repeated past actions in an established past context. Use used to for past states; would alone does not normally describe an old state such as owning a house.','Тодорхой өнгөрсөн нөхцөл дэх давтагддаг үйлдэлд would + үндсэн үйл үг хэрэглэнэ. Өнгөрсөн төлөвт used to хэрэглэнэ; would-оор өмнө байшинтай байсан зэрэг төлөвийг дангаар хэлэхгүй.','As a child, I would play … · I used to own …','Every summer, we would visit our cousins.','Зун бүр бид үеэлүүд дээрээ очдог байсан.','I ___ own a red bicycle, but I sold it.','used to','would to','was used to','Every summer, we would visited our cousins.'],
    ['Advanced passive forms','Үйлдэгдэх хэвийн нийлмэл хэлбэр','The passive can appear in continuous, perfect and modal structures. Keep the required auxiliary chain: is being repaired, has been repaired, must be repaired. Choose tense according to the intended time.','Үйлдэгдэх хэв нь үргэлжилсэн, төгс, модал бүтэцтэй байж болно. Is being repaired, has been repaired, must be repaired гэх туслах үйл үгийн дарааллыг хадгална. Цагаа утгад тохируулна.','be being done · have been done · modal + be done','The road is being repaired this week.','Энэ долоо хоногт замыг засаж байна.','The documents must ___ today.','be signed','been signed','be signing by someone','The road is being repair this week.'],
    ['Have/get something done','Бусдаар хийлгэх бүтэц','Use have/get + object + past participle when someone performs a service for you or when you experience an event affecting something you own. The subject is not necessarily the person doing the action.','Өөртөө үйлчилгээ хийлгэх эсвэл өөрийн зүйлд үйл явдал тохиолдохыг have/get + объект + past participle-ээр хэлнэ. Өгүүлбэрийн эзэн үйлдлийг өөрөө хийдэг гэсэн үг биш.','have/get + object + past participle','I had my hair cut yesterday.','Би өчигдөр үсээ засуулсан.','We are having our house ___.','painted','paint','to paint','I had my hair to cut yesterday.'],
    ['Reporting passives','Мэдээлэл дамжуулах үйлдэгдэх хэв','Use It is said/believed that … or subject + is said/believed + to-infinitive for impersonal reporting. Use to have + past participle when the reported event precedes the report.','Ерөнхий эх сурвалжтай мэдээллийг It is said/believed that … эсвэл эзэн + is said/believed + to-infinitive хэлбэрээр дамжуулна. Өмнө болсон үйлдэлд to have + past participle хэрэглэнэ.','It is said that … · He is said to have left.','The painting is believed to be very old.','Тэр зургийг маш эртнийх гэж үздэг.','She is said ___ the prize last year.','to have won','to won','having win','The painting is believed be very old.'],
    ['Non-defining relative clauses','Нэмэлт мэдээллийн хамаатуулах өгүүлбэр','Use commas around a non-defining relative clause. It adds extra information rather than identifying which noun. Use who/which/whose, not that, and do not omit the relative pronoun.','Аль нэр болохыг ялгах бус нэмэлт мэдээлэл өгч буй relative clause-ыг таслалаар салгана. Who/which/whose хэрэглэж, that хэрэглэхгүй; хамаатуулах үгийг орхихгүй.','Sara, who lives nearby, … · My car, which …','My brother, who lives in Canada, is visiting us.','Канадад амьдардаг ах маань бидэн дээр зочилж байна.','My bike, ___ I bought last year, is broken.','which','that','what','My brother, that lives in Canada, is visiting us.'],
    ['Whose, where and preposition relatives','Whose, where ба угтвар үгтэй relative','Whose shows possession; where relates to places. In formal clauses, a preposition can precede whom/which. In ordinary speech it often goes at the end. Do not add a redundant object pronoun.','Whose нь хамаарал, where нь газрыг заана. Албан найруулгад угтвар үгийг whom/which-ийн өмнө тавьж болно; ярианд төгсгөлд орж болно. Объектын төлөөний үгийг давхар нэмж болохгүй.','the person to whom I spoke · the person I spoke to','That is the author whose book won the prize.','Тэр бол ном нь шагнал авсан зохиолч.','This is the town ___ I grew up.','where','which in it','who','That is the author who his book won the prize.'],
    ['Participle clauses','Причастын товчилсон өгүүлбэр','Use an -ing clause for an active meaning and a past-participle clause for a passive meaning. The implied subject normally matches the main clause subject. A having + participle clause marks an earlier action.','Идэвхтэй утгад -ing, үйлдэгдэх утгад past participle-тай товчилсон хэсэг хэрэглэнэ. Далд эзэн нь гол өгүүлбэрийн эзэнтэй ихэвчлэн ижил байна. Having + participle нь өмнөх үйлдлийг заана.','Walking home, I … · Built in 1900, the house …','Feeling tired, she went to bed early.','Ядарсан тул тэр эрт унтсан.','___ the work, he went home.','Having finished','Have finished','Finished he','Feeling tired, the bed was comfortable.'],
    ['Must have, can’t have, needn’t have','Өнгөрсөн таамаг ба шаардлагагүй үйлдэл','Must have and can’t have express strong deductions about the past. Needn’t have done means an action happened but was unnecessary. Didn’t need to does not itself tell us whether the action happened.','Must have/can’t have нь өнгөрсөн тухай баттай эерэг/сөрөг дүгнэлт. Needn’t have done нь хийсэн боловч шаардлагагүй байсныг хэлнэ. Didn’t need to дангаараа хийсэн эсэхийг батлахгүй.','must/can’t/needn’t + have + past participle','You needn’t have bought milk; we already had some.','Сүү авах шаардлагагүй байсан; бидэнд байсан шүү дээ.','He was abroad. He ___ been at the meeting.','can’t have','must have to','can’t has','You needn’t have buy milk.'],
    ['Reporting verbs and patterns','Дамжуулах үйл үгийн хэвүүд','Different reporting verbs take different complements. Advise takes object + to-infinitive; suggest takes -ing or a that-clause; deny takes -ing. Learn the whole pattern, not just the verb.','Дамжуулах үйл үг бүр өөр нөхөх бүтэцтэй. Advise-ийн дараа объект + to-infinitive, suggest-ийн дараа -ing эсвэл that хэсэг, deny-ийн дараа -ing орно. Үгийг бүтцийн хамт сурна.','advised me to go · suggested going · denied taking','She suggested taking the earlier train.','Тэр эртний галт тэргээр явахыг санал болгосон.','He advised me ___ a doctor.','to see','seeing to','see','She suggested me to take the earlier train.'],
    ['Verb patterns: perception and causation','Мэдрэх ба үйлдүүлэх үйл үгийн бүтэц','Make/let + object takes a bare infinitive; be made takes to-infinitive. See/hear + object + base verb can present a whole event, while -ing presents an action in progress.','Make/let + объектын дараа to-гүй үйл үг, be made-ийн дараа to-infinitive орно. See/hear + объект + үндсэн үйл үг нь бүтэн үйл явдал, -ing нь үргэлжилж буй хэсгийг илэрхийлж болно.','made me wait · was made to wait · saw him running','The teacher made us rewrite the essay.','Багш биднээр эсээг дахин бичүүлсэн.','We were made ___ outside.','to wait','wait','waiting to','The teacher made us to rewrite the essay.'],
    ['Articles: general and specific reference','Ерөнхий ба тодорхой утгын ялгац','Plural and uncountable nouns often use no article for general reference. Use the for a specific group or item. Institutions can have special article patterns: go to school as a pupil, visit the school as a building.','Ерөнхий утгатай олон тооны болон тоологдохгүй нэр ихэвчлэн ялгацгүй. Тодорхой зүйл, бүлэгт the хэрэглэнэ. Go to school нь сурахаар очих, visit the school нь барилгад зочлох зэрэг ялгаатай.','Children need sleep. · The children next door …','Music helps me relax, but the music here is too loud.','Хөгжим намайг тайвшруулдаг ч эндхийн хөгжим хэт чанга байна.','___ life is full of surprises. (in general)','—','The','A','I enjoy a music.'],
    ['Advanced comparison and intensifiers','Харьцуулалтыг нарийвчлах','Use much/far/a lot to strengthen a comparative and a bit/slightly to soften it. Use as … as for equality and the + comparative … the + comparative for linked changes.','Харьцуулсан зэргийг much/far/a lot-оор хүчтэй, a bit/slightly-гаар сулруулна. Тэнцүүг as … as, хамааран өөрчлөгдөхийг the + comparative … the + comparative-ээр хэлнэ.','far better · slightly cheaper · the more … the better','The more you practise, the easier it becomes.','Дасгал хийх тусам улам амархан болдог.','This version is ___ better than the old one.','far','very','most','The more you practise, easier it becomes.'],
    ['Gradable and non-gradable adjectives','Зэрэглэж болох ба туйлын тэмдэг нэр','Use very with gradable adjectives such as cold and absolutely with extreme or non-gradable meanings such as freezing or impossible. Collocations vary, so learn common combinations.','Cold зэрэг хэмжээгээр өөрчлөгдөх тэмдэг нэртэй very, freezing/impossible зэрэг туйлын утгатай үгтэй absolutely түгээмэл хэрэглэнэ. Үгсийн нийцлийг хосоор нь сурах хэрэгтэй.','very tired · absolutely exhausted · completely impossible','After the race, she was absolutely exhausted.','Уралдааны дараа тэр туйлдаа хүртэл ядарсан.','The task is ___ impossible.','absolutely','a few','many','She was many exhausted after the race.'],
    ['Future time clauses','Ирээдүйн цагийн дагавар өгүүлбэр','After when, as soon as, until and before in a future time clause, normally use a present form, not will. Present perfect can emphasise completing the first action before the next.','When, as soon as, until, before-той ирээдүйн цагийн хэсэгт ихэвчлэн will бус одоо цаг хэрэглэнэ. Эхний үйлдэл дууссаныг онцлоход present perfect хэрэглэж болно.','I’ll call when I arrive. · after I have finished','I will message you as soon as I land.','Газардмагцаа чамд зурвас бичнэ.','We will leave after she ___.','arrives','will arrive','will arriving','I will message you as soon as I will land.'],
    ['Condition alternatives: unless, provided, in case','Unless / provided / in case','Unless means if not; provided/as long as set a condition. In case describes a precaution for a possibility and is not interchangeable with if. Avoid adding a second negative after unless unless genuinely intended.','Unless нь if not, provided/as long as нь нөхцөл тавина. In case нь болзошгүй тохиолдолд бэлтгэх утгатай тул if-тэй адил биш. Unless-ийн араас санаандгүй давхар үгүйсгэл бүү нэм.','unless it rains · provided you pay · take an umbrella in case','Take a coat in case it gets cold.','Хүйтрэх магадлалтай тул хүрэм аваарай.','You can borrow it ___ you return it tomorrow.','provided that','in case of','unless if','Take a coat in case of it gets cold.'],
  ],
  C1: [
    ['Negative inversion','Үгүйсгэсэн дайвар үгийн урвуу дараалал','When a negative or restrictive expression starts a clause for emphasis, invert the subject and auxiliary. Use do-support if there is no auxiliary. The inversion occurs in the main clause after only when/not until.','Үгүйсгэсэн эсвэл хязгаарласан хэллэгийг өгүүлбэрийн эхэнд онцлон тавихад туслах үйл үг, эзний байрлалыг солино. Туслах үггүй бол do хэрэглэнэ. Only when/not until-ийн дараа гол өгүүлбэр урвуу болно.','Never have I … · Rarely does she … · Only then did I …','Never have I seen such a beautiful sky.','Би ийм үзэсгэлэнтэй тэнгэр огт харж байгаагүй.','Rarely ___ such a clear explanation.','do we hear','we hear','we do hear','Never I have seen such a beautiful sky.'],
    ['Hardly, scarcely and no sooner','Hardly / scarcely / no sooner','Use hardly/scarcely + past perfect + when, and no sooner + past perfect + than, to show one event immediately following another. Invert after the opening adverbial.','Нэг үйл явдал дуусмагц нөгөө нь болсныг hardly/scarcely + past perfect + when, no sooner + past perfect + than гэж хэлнэ. Эхэнд тавьсан үед туслах үг, эзэн урвуу байрлана.','Hardly had … when … · No sooner had … than …','Hardly had we arrived when it began to snow.','Биднийг ирмэгц цас орж эхэлсэн.','No sooner had she sat down ___ the phone rang.','than','when','that','Hardly we had arrived than it began to snow.'],
    ['Conditional inversion','Нөхцөлийн урвуу бүтэц','In formal conditionals, omit if and invert had, were or should with the subject. Had I known means if I had known; were I to go imagines a possibility; should you need is tentative.','Албан нөхцөлийн өгүүлбэрт if-ийг хасаад had, were, should-ыг эзний өмнө гаргаж болно. Had I known нь if I had known, were I to go нь төсөөлөл, should you need нь болзошгүй нөхцөл.','Had I known … · Were I to … · Should you need …','Had I known the truth, I would have acted differently.','Үнэнийг мэдсэн бол би өөрөөр хандах байсан.','___ you need assistance, please call us.','Should','Would','Did','Had known I the truth, I would have acted differently.'],
    ['Cleft sentences with it','It-cleft: онцолсон өгүүлбэр','Use It is/was + focused phrase + that/who-clause to highlight a person, time, place or reason. Preserve the original meaning and agreement in the remaining clause.','Хүн, цаг, газар, шалтгааныг онцлоход It is/was + онцлох хэсэг + that/who хэсэг хэрэглэнэ. Үлдсэн хэсгийн утга ба үйл үгийн зохицлыг хадгална.','It was Anna who called. · It was yesterday that …','It was the noise that woke me up.','Намайг сэрээсэн зүйл нь тэр чимээ байсан.','It was Sara ___ solved the problem.','who','what','whose she','It the noise was that woke me up.'],
    ['What-clefts and all-clefts','What / all-тай онцолсон бүтэц','Use a what-clause as subject or complement to focus on a thing, action or need. All … is/was can emphasise the only thing. With do, the focused verb can be a bare infinitive.','Зүйл, үйлдэл, хэрэгцээг онцлоход what-тай хэсгийг эзэн эсвэл нөхөх гишүүн болгоно. All … is/was нь цорын ганц зүйлийг онцолно. Do орсон үед онцолсон үйл үг to-гүй байж болно.','What I need is … · All I did was (to) …','What I need is a little more time.','Надад хэрэгтэй зүйл бол арай илүү хугацаа.','All she wanted ___ a fair chance.','was','were being','did','What I need a little more time is.'],
    ['Fronting and emphatic do','Урд байрлуулах ба онцлох do','Move an object or complement to the front for contrast in suitable contexts. Emphatic do/does/did strengthens an affirmative main verb, which stays in base form. Fronting does not always cause inversion.','Тохирох нөхцөлд объект, нөхөх хэсгийг урд тавьж эсрэгцүүлэн онцолно. Do/does/did-ээр батлах үйл үгийг онцлоход гол үйл үг үндсэн хэлбэртэй байна. Урд тавих бүрд урвуу дараалал хэрэггүй.','That book, I enjoyed. · I do understand.','I did send the email; please check your inbox.','Би зурвасыг үнэхээр илгээсэн; ирсэн хайрцгаа шалгаарай.','She does ___ what you mean.','understand','understands','understood','I did sent the email.'],
    ['Ellipsis and substitution','Үг хураах ба орлуулах','Avoid repetition by omitting recoverable words or substituting do so, one/ones, so and not. Keep enough grammatical structure for the listener to recover the meaning. Auxiliary-only replies often omit a repeated verb phrase.','Ойлгомжтой давталтыг хасах эсвэл do so, one/ones, so, not-оор орлуулна. Сонсогч утгыг сэргээх хангалттай бүтэц үлдээнэ. Туслах үйл үгээр төгссөн хариултад давтагдсан үйл хэсгийг хурааж болно.','I hope so. · I hope not. · She can, but I can’t.','I haven’t finished, but she has.','Би дуусаагүй ч тэр дууссан.','Will it rain? — I hope ___. We need dry weather.','not','no it','not so it','I haven’t finished, but she has finished it has.'],
    ['Nominalisation','Үйл явцыг нэршүүлэх','Nominalisation turns verbs or adjectives into nouns and can make formal writing more compact. Preserve the actor, logical relations and article choices. Too much nominalisation can make writing difficult to follow.','Үйл үг, тэмдэг нэрийг нэршүүлж албан найруулгыг нягтруулж болно. Үйлдэгч, логик холбоо, ялгац гишүүнийг зөв хадгална. Хэт их нэршүүлэх нь ойлгомжийг бууруулдаг.','They decided to leave. → Their decision to leave …','The introduction of the policy caused debate.','Бодлогыг нэвтрүүлсэн нь хэлэлцүүлэг өрнүүлсэн.','Their ___ of the offer surprised us.','rejection','reject','rejecting to','The introduce of the policy caused debate.'],
    ['Hedging and degrees of certainty','Болгоомжтой дүгнэлт ба итгэлийн зэрэг','Use may, appear to, tend to, arguably and it seems that to avoid overstating evidence. A hedge changes the strength of a claim. Match it to the evidence rather than adding uncertainty mechanically.','Нотолгооноос хэтрүүлэн батлахгүйн тулд may, appear to, tend to, arguably, it seems that хэрэглэнэ. Эдгээр нь мэдэгдлийн хүчийг өөрчилнө. Нотолгоондоо тохируулан сонгоно.','The results may suggest … · It appears that …','The findings appear to support the hypothesis.','Үр дүн таамаглалыг дэмжиж байгаа бололтой.','These results ___ indicate a wider trend. (cautious claim)','may','must definitely always','are may','The findings appear support the hypothesis.'],
    ['Mandative subjunctive','Шаардлага, саналын subjunctive','After expressions such as it is essential that and recommend that, formal English can use a base verb for every subject. British English also commonly uses should + base verb. The negative is not + base verb.','It is essential that, recommend that зэрэг шаардлага, саналын дараа албан хэлэнд бүх эзэнтэй үндсэн үйл үг хэрэглэж болно. Британи хэлэнд should + үндсэн үйл үг ч түгээмэл. Үгүйсгэл нь not + үндсэн хэлбэр.','It is essential that she be … · recommend that he attend','They insisted that every member be informed.','Тэд гишүүн бүрт мэдээлэхийг шаардсан.','It is vital that he ___ present.','be','is being to','been','They insisted that every member be informs.'],
    ['Unreal past and would rather','Бодит бус өнгөрсөн хэлбэр ба would rather','After it’s time, a past form can refer to what should happen now. Would rather + same subject uses a bare infinitive; with a different subject, use a past form for present/future preference.','It’s time-ийн дараах өнгөрсөн хэлбэр нь одоо хийх ёстойг зааж болно. Would rather нь ижил эзэнтэй бол to-гүй үйл үг, өөр эзэнтэй бол одоо/ирээдүйн хүсэлд past хэлбэр авна.','It’s time we left. · I’d rather stay. · I’d rather you stayed.','I would rather you did not tell anyone.','Чамайг хэнд ч хэлэхгүй байгаасай гэж хүсэж байна.','It is time we ___ home.','went','goes','will go','I would rather you not to tell anyone.'],
    ['Advanced modal meanings','Модал үгийн нарийн утга','Modals can express stance as well as time. Would can distance a claim; will can describe typical behaviour; should can express expectation or surprise. Read the context rather than treating each modal as one fixed translation.','Модал үг нь цаг төдийгүй хандлагыг илэрхийлнэ. Would нь зөөлрүүлэх, will нь хэвшмэл зан, should нь хүлээлт эсвэл гайхал илэрхийлж болно. Нэг тогтсон орчуулгаар бус нөхцөлөөр ойлгоно.','That would be … · Accidents will happen. · He should be …','The parcel should arrive by Friday.','Илгээмж баасан гараг гэхэд ирэх ёстой гэж хүлээж байна.','That ___ be the courier at the door. (tentative identification)','would','would to','would been','The parcel should to arrive by Friday.'],
    ['Complex passive infinitives and gerunds','Үйлдэгдэх infinitive ба gerund','Use to be done and being done for passive infinitives and gerunds. Use to have been done or having been done for an earlier passive event. Select the form required by the preceding verb or preposition.','Үйлдэгдэх infinitive-д to be done, gerund-д being done хэрэглэнэ. Өмнөх үйлдэгдэх үйл явдалд to have been done / having been done хэрэглэнэ. Өмнөх үйл үг, угтвар үгийн шаардлагад тохируулна.','to be invited · being invited · having been invited','She appreciated being invited to the discussion.','Тэр хэлэлцүүлэгт уригдсандаа талархсан.','He seems ___ about the change already.','to have been informed','to have informed by someone','being inform','She appreciated to be invited to the discussion.'],
    ['Perfect participle clauses','Төгс participle товчлол','Having + past participle marks an action completed before the main event. Having been + past participle is passive. Check that the understood subject matches the subject of the main clause.','Having + past participle нь гол үйл явдлаас өмнө дууссан үйлдэл, having been + past participle нь үйлдэгдэх утга заана. Далд эзнийг гол өгүүлбэрийн эзэнтэй тааруулна.','Having finished, she … · Having been warned, they …','Having been warned about the ice, we drove slowly.','Мөстэйг анхааруулсан тул бид удаан явсан.','___ the contract, she kept a copy.','Having signed','Have signed','Having sign','Having been warned about the ice, the road was driven slowly.'],
    ['Absolute and verbless clauses','Бие даасан ба үйл үггүй товчлол','An absolute clause has its own noun subject and adds background. Verbless clauses omit a recoverable form of be, often after when, while or if. Use these compact forms only when the reference is clear.','Absolute clause нь өөрийн нэрэн эзэнтэй бөгөөд арын нөхцөл нэмдэг. Үйл үггүй товчлолд ойлгомжтой be-г, ихэвчлэн when/while/if-ийн дараа хасна. Утгын холбоо тодорхой үед хэрэглэнэ.','Weather permitting, … · If necessary, …','Weather permitting, the event will be outdoors.','Цаг агаар зөвшөөрвөл арга хэмжээ гадаа болно.','If ___, please contact the office.','necessary','necessarily it','necessity','Weather permits, the event will be outdoors.'],
    ['Concession: however, whatever, no matter','Буулт илэрхийлэх нийлмэл бүтэц','However + adjective/adverb means no matter how. Whatever + noun or clause means it does not matter what. These clauses acknowledge a condition without changing the main result.','However + тэмдэг/дайвар үг нь no matter how, whatever + нэр/өгүүлбэр нь юу ч байсан гэсэн утгатай. Нөхцөлийг зөвшөөрсөн ч гол үр дүн өөрчлөгдөхгүйг хэлнэ.','However difficult it is, … · Whatever happens, …','However hard she tried, she could not open it.','Тэр хэчнээн хичээсэн ч онгойлгож чадаагүй.','___ happens, we will support you.','Whatever','However what','Despite of','However she tried hard, she could not open it.'],
    ['Complex noun phrases and agreement','Нийлмэл нэрийн бүлэг ба зохицол','Find the head noun before choosing verb agreement. Intervening phrases do not change it. A number of + plural normally takes a plural verb; the number of takes a singular verb. Collective-noun agreement can vary by variety and meaning.','Үйл үгээ сонгохоос өмнө бүлгийн гол нэрийг олно. Дунд орсон тодотгол гол нэрийн тоог өөрчлөхгүй. A number of + олон тоо нь ихэвчлэн олон тооны, the number of нь ганц тооны үйл үг авна.','The list of names is … · A number of people are …','The number of applicants has increased.','Өргөдөл гаргагчдын тоо нэмэгдсэн.','A number of students ___ absent today.','are','is','has being','The number of applicants have increased.'],
    ['Adverb scope and stance','Дайвар үгийн хамрах хүрээ','Position changes what an adverb modifies. Only can restrict a subject, action or object. Sentence adverbs such as apparently and frankly comment on evidence or speaker attitude rather than describing how the action happens.','Дайвар үгийн байрлал тодорхойлж буй хэсгийг өөрчилнө. Only нь эзэн, үйлдэл, объектыг хязгаарлаж болно. Apparently/frankly нь үйлдлийн арга бус нотолгоо, яригчийн хандлагыг илэрхийлнэ.','Only Sara called. · Sara only called. · Sara called only me.','Only Sara knew the answer.','Зөвхөн Сара л хариултыг мэдэж байсан.','___, the meeting has been cancelled. (based on what I heard)','Apparently','Apparent','Appearance','Only knew Sara the answer.'],
    ['Reference, substitution and cohesion','Заалт, орлуулалт ба уялдаа','Use this/that, the former/latter, such and which to link to a clear earlier idea. Which can refer to a whole preceding clause. Avoid a pronoun whose reference could be confused with two different nouns.','This/that, the former/latter, such, which-ээр өмнөх тодорхой санааг холбоно. Which нь өмнөх бүтэн өгүүлбэрийг зааж болно. Хоёр өөр нэрийн алиныг зааж буй нь бүдэг төлөөний үгээс зайлсхий.','She resigned, which surprised us. · the former / the latter','He missed the deadline, which caused a delay.','Тэр хугацаандаа амжаагүй нь саатал үүсгэсэн.','Tea and coffee were offered; I chose the ___. (coffee)','latter','former','latest one of former','He missed the deadline, what caused a delay.'],
    ['Advanced future and future in the past','Нарийн ирээдүй ба өнгөрснөөс харах ирээдүй','Use was going to for a past intention, would for future from a past viewpoint, be about to for immediacy and be due to for an expected schedule. Was to have + participle can describe an arrangement that did not occur.','Өнгөрсөн төлөвлөгөөнд was going to, өнгөрснөөс харах ирээдүйд would, яг болох гэж байгаад be about to, хуваарьт be due to хэрэглэнэ. Was to have + participle нь хэрэгжээгүй тохиролцоог зааж болно.','was going to · would later · is about to · is due to','I was going to call, but my battery died.','Би утасдах гэж байсан ч цэнэг дууссан.','The train is due ___ at noon.','to arrive','arriving to','arrive','I was going call, but my battery died.'],
  ],
};

export const lessons = Object.entries(curriculum).flatMap(([level, rows]) => rows.map((row, index) => {
  const [titleEn, titleMn, ruleEn, ruleMn, pattern, example, exampleMn, gap, answer, wrong1, wrong2, incorrect] = row;
  const options = [answer, wrong1, wrong2];
  const shift = index % options.length;
  const rotated = options.slice(shift).concat(options.slice(0, shift));
  const sentences = index % 2 ? [incorrect, example] : [example, incorrect];
  return {
    id: `${level.toLowerCase()}-${String(index + 1).padStart(2, '0')}`, level,
    title: { en: titleEn, mn: titleMn }, rule: { en: ruleEn, mn: ruleMn },
    pattern, example, exampleMn,
    questions: [
      { type: 'gap', prompt: gap, options: rotated, correct: rotated.indexOf(answer) },
      { type: 'sentence', prompt: '', options: sentences, correct: sentences.indexOf(example) },
    ],
  };
}));
